CREATE TABLE IF NOT EXISTS sources (id TEXT PRIMARY KEY, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settings (id TEXT PRIMARY KEY, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ingested_items (id TEXT PRIMARY KEY, source_id TEXT NOT NULL, canonical_url TEXT NOT NULL, content_hash TEXT NOT NULL, payload TEXT NOT NULL, imported_at TEXT NOT NULL, UNIQUE(source_id, canonical_url));
CREATE TABLE IF NOT EXISTS events (id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, title TEXT NOT NULL, status TEXT NOT NULL, payload TEXT NOT NULL, published_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS generated_summaries (id TEXT PRIMARY KEY, event_id TEXT NOT NULL, input_hash TEXT NOT NULL, payload TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS citations (id TEXT PRIMARY KEY, event_id TEXT NOT NULL, item_id TEXT NOT NULL, payload TEXT NOT NULL, UNIQUE(event_id, item_id));
CREATE TABLE IF NOT EXISTS article_versions (id TEXT PRIMARY KEY, event_id TEXT NOT NULL, payload TEXT NOT NULL, reason TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS editorial_reviews (id TEXT PRIMARY KEY, event_id TEXT NOT NULL, candidate TEXT NOT NULL, reasons TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS corrections (id TEXT PRIMARY KEY, event_id TEXT NOT NULL, payload TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS pipeline_runs (id TEXT PRIMARY KEY, payload TEXT NOT NULL, started_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS pipeline_locks (id TEXT PRIMARY KEY, owner TEXT NOT NULL, expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ai_usage (id TEXT PRIMARY KEY, run_id TEXT NOT NULL, day TEXT NOT NULL, input_tokens INTEGER NOT NULL, output_tokens INTEGER NOT NULL, reserved_usd REAL NOT NULL, actual_usd REAL NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS daily_digests (id TEXT PRIMARY KEY, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS daily_metrics (day TEXT PRIMARY KEY, page_views INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS reports (id TEXT PRIMARY KEY, kind TEXT NOT NULL, article_id TEXT, message TEXT NOT NULL, email TEXT, created_at TEXT NOT NULL, status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rate_limits (key TEXT PRIMARY KEY, count INTEGER NOT NULL, reset_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS events_publication_idx ON events(status, published_at);
CREATE INDEX IF NOT EXISTS ingestion_date_idx ON ingested_items(imported_at);
CREATE INDEX IF NOT EXISTS versions_event_idx ON article_versions(event_id, created_at);
CREATE INDEX IF NOT EXISTS review_event_idx ON editorial_reviews(event_id, status);
